"""Generate the native HTML entity table from the WHATWG character reference data."""

import json
from pathlib import Path
from urllib.request import urlopen

SOURCE = "https://html.spec.whatwg.org/entities.json"
OUTPUT = Path(__file__).resolve().parents[1] / "native/rust/text_core/src/entities.rs"


def main():
    with urlopen(SOURCE, timeout=60) as response:
        entities = json.load(response)
    lines = [
        "// WHATWG HTML named character references: https://html.spec.whatwg.org/entities.json",
        "// Generated by scripts/generate-rust-html-entities.py. WHATWG data: CC BY 4.0.",
        "pub static ENTITIES: &[(&str, &[u16])] = &[",
    ]
    for key, item in sorted(entities.items()):
        units = []
        for code in item["codepoints"]:
            if code <= 0xFFFF:
                units.append(code)
            else:
                code -= 0x10000
                units.extend([0xD800 + (code >> 10), 0xDC00 + (code & 1023)])
        lines.append(f'    ("{key[1:]}", &{units}),')
    lines.append("];\n")
    OUTPUT.write_text("\n".join(lines), encoding="utf-8")
    print(f"Generated {len(entities)} named character references")


if __name__ == "__main__":
    main()
